import re
# Extract the search_direct_flight section from skill_info
skill_text = skill_info
# Find tool definitions
matches = re.findall(r'search_direct_flight.*?(?=\n##|\Z)', skill_text, re.DOTALL)
if matches:
    for m in matches[:2]:
        print(m[:1000])
else:
    # Look for the tools section
    tool_section = re.findall(r'Tool[s]?\s*(?:Reference|List|Overview).*?(?=\n##\s|\Z)', skill_text, re.DOTALL | re.IGNORECASE)
    if tool_section:
        print(tool_section[0][:2000])
    else:
        # Just print a chunk around "search"
        idx = skill_text.lower().find('search')
        if idx >= 0:
            print(skill_text[max(0,idx-200):idx+800])
        else:
            print("No search found. Printing last 2000 chars:")
            print(skill_text[-2000:])
